sfsqlquery.SqlTester.clearMocks();
System.assertEquals(false, sfsqlquery.SqlTester.isRunningTest());
ConnectApi.QuerySqlRow firstRaw = new ConnectApi.QuerySqlRow();
firstRaw.row = new List<Object>{'first'};
ConnectApi.QuerySqlRow secondRaw = new ConnectApi.QuerySqlRow();
secondRaw.row = new List<Object>{'second'};
ConnectApi.QuerySqlMetadataItem metadata = new ConnectApi.QuerySqlMetadataItem();
metadata.name = 'Name';
sfsqlquery.SqlTester.setMockRows(new List<ConnectApi.QuerySqlRow>{firstRaw});
sfsqlquery.SqlTester.enqueueMockRows(new List<ConnectApi.QuerySqlRow>{secondRaw});
sfsqlquery.SqlTester.setMockMetadata(new List<ConnectApi.QuerySqlMetadataItem>{metadata});
sfsqlquery.QueryHandle emptyHandle = new sfsqlquery.QueryHandle();
System.assertNotEquals(null, emptyHandle);
sfsqlquery.QueryHandle handle = sfsqlquery.QueryHandle.create('query-1', 'default');
System.assertEquals(handle, handle.withOffset(5));
System.assertEquals(handle, handle.withWorkloadName('local-work'));
sfsqlquery.SqlQueueable queued = new sfsqlquery.SqlQueueable(handle);
System.assertEquals('query-1', queued.getQueryId());
System.assertEquals(0, queued.getColumnNames().size());
System.assertEquals(0, queued.getMetadata().size());
System.assertNotEquals(null, queued.getRows());
System.assertNotEquals(null, queued.getPageOutput());
queued.chainNextJob(sfsqlquery.QueryHandle.create('query-2', 'default'));
queued.processDataChunk();
queued.cancel();
sfsqlquery.SqlRowIterator rows = new sfsqlquery.SqlRowIterator(handle);
System.assertEquals('query-1', rows.getQueryId());
System.assertEquals(1, rows.getMetadata().size());
System.assertEquals('Name', rows.getColumnNames().get(0));
System.assertEquals(true, rows.hasNext());
System.assertEquals(rows, rows.iterator());
sfsqlquery.Row first = rows.next();
ConnectApi.QuerySqlRow firstRow = first.getRawRow();
System.assertEquals('first', ((List<Object>)firstRow.row).get(0));
System.assertEquals(true, rows.hasNext());
sfsqlquery.SqlRowIterator cancellable = new sfsqlquery.SqlRowIterator(handle);
cancellable.cancel();
System.assertEquals(false, cancellable.hasNext());
sfsqlquery.SqlStatement emptyStatement = new sfsqlquery.SqlStatement();
System.assertNotEquals(null, emptyStatement);
sfsqlquery.SqlStatement sqlStatement = sfsqlquery.SqlStatement.create('select Name from Account', 'default');
ConnectApi.QuerySqlInput input = new ConnectApi.QuerySqlInput();
input.sql = 'select Id from Account';
sfsqlquery.SqlStatement inputStatement = sfsqlquery.SqlStatement.create(input, 'default');
System.assertEquals(inputStatement, inputStatement.withWorkloadName('input-work'));
sfsqlquery.SqlRowIterator statementRows = new sfsqlquery.SqlRowIterator(sqlStatement);
System.assertEquals(1, statementRows.getMetadata().size());

